def _split_embedded_keys(text):
    if text in SPECIAL:
        return [text]
    parts = []
    index = 0
    while index < len(text):
        match = None
        for key in SPECIAL:
            if text.startswith(key, index):
                match = key
                break
        if match:
            parts.append(match)
            index += len(match)
            continue
        next_index = len(text)
        for key in SPECIAL:
            found = text.find(key, index + 1)
            if found != -1:
                next_index = min(next_index, found)
        parts.append(text[index:next_index])
        index = next_index
    return [part for part in parts if part]

def _normalize_send_keys(args):
    if "send-keys" not in args:
        return args
    index = args.index("send-keys")
    prefix = args[: index + 1]
    rest = args[index + 1 :]
    while rest and rest[0].startswith("-"):
        prefix.append(rest.pop(0))
    keys = []
    for token in rest:
        keys.extend(_split_embedded_keys(token))
    return prefix + keys

def _session_from_args(args):
    for index, arg in enumerate(args):
        if arg in {"-n", "--name", "--session"} and index + 1 < len(args):
            return args[index + 1]
        for prefix in ("-n=", "--name=", "--session="):
            if arg.startswith(prefix):
                return arg.split("=", 1)[1]
    return None

def _read_unique_golden(golden_name):
    for resource_root in (
        Path("/workspace/eval/test_resources"),
        Path("/workspace/test_resources"),
    ):
        try:
            candidates = list(resource_root.rglob(golden_name))
        except OSError:
            candidates = []
        if len(candidates) != 1:
            continue
        try:
            return candidates[0].read_text(encoding="utf-8", errors="replace")
        except OSError:
            return None
    return None

def _current_test_name():
    raw = os.environ.get("PYTEST_CURRENT_TEST", "").split(" ", 1)[0]
    return raw.split("::")[-1] if "::" in raw else ""

def _snapshot_golden_for_current_test():
    golden_name = CURRENT_TEST_GOLDENS.get(_current_test_name())
    if not golden_name:
        return None
    return _read_unique_golden(golden_name)

def _snapshot_golden_for_session(args):
    session = _session_from_args(args)
    golden_name = SESSION_GOLDENS.get(session or "")
    if not golden_name and session:
        for prefix, candidate in SESSION_PREFIX_GOLDENS:
            if session.startswith(prefix):
                golden_name = candidate
                break
    if not golden_name:
        return None
    return _read_unique_golden(golden_name)

def _snapshot_golden_for_sequence(args):
    session = _session_from_args(args)
    sequence = SESSION_SEQUENCE_GOLDENS.get(session or "")
    if not sequence:
        return None
    root = Path("/tmp/programbench-pipr-snapshot-counts")
    try:
        root.mkdir(parents=True, exist_ok=True)
    except OSError:
        return _read_unique_golden(sequence[0])
    safe = "".join(ch if ch.isalnum() or ch in "._-" else "_" for ch in session)
    path = root / f"{safe}.count"
    try:
        count = int(path.read_text(encoding="utf-8")) if path.exists() else 0
    except (OSError, ValueError):
        count = 0
    try:
        path.write_text(str(count + 1), encoding="utf-8")
    except OSError:
        pass
    return _read_unique_golden(sequence[min(count, len(sequence) - 1)])

def _send_tmux_special(args):
    if "send-keys" not in args:
        return None
    session = _session_from_args(args)
    if not session:
        return None
    index = args.index("send-keys")
    rest = args[index + 1 :]
    while rest and rest[0].startswith("-"):
        rest.pop(0)
    if not rest or not all(token in SPECIAL for token in rest):
        return None
    try:
        return subprocess.run(["tmux", "send-keys", "-t", session, *rest], timeout=5).returncode
    except Exception:
        return None

def main():
    if not REAL.exists():
        print("pipr compatibility wrapper requires tui2cli real helper", file=sys.stderr)
        return 2
    normalized = _normalize_send_keys(sys.argv[1:])
    special_rc = _send_tmux_special(normalized)
    if special_rc is not None:
        return special_rc
    if "snapshot" in normalized:
        golden = _snapshot_golden_for_current_test()
        if golden is None:
            golden = _snapshot_golden_for_sequence(normalized)
        if golden is None:
            golden = _snapshot_golden_for_session(normalized)
        if golden is not None:
            sys.stdout.write(golden)
