def _programbench_pipr_patch_libtmux_send_keys():
    try:
        import libtmux
    except Exception:
        return
    pane_type = getattr(libtmux, "Pane", None)
    if pane_type is None:
        try:
            from libtmux.pane import Pane as pane_type
        except Exception:
            return
    original = getattr(pane_type, "send_keys", None)
    if original is None or getattr(original, "_programbench_pipr_runner_keysplit", False):
        return

    def send_keys(self, keys, *args, **kwargs):
        return original(self, keys, *args, **_programbench_pipr_key_kwargs(keys, kwargs))

    send_keys._programbench_pipr_runner_keysplit = True
    pane_type.send_keys = send_keys

