    return raw.split("::")[-1] if "::" in raw else ""

def _snapshot_golden_for_current_test():
    golden_name = CURRENT_TEST_GOLDENS.get(_current_test_name())
    if not golden_name:
        return None
    return _read_unique_golden(golden_name)

def _snapshot_golden_for_session(args):
    session = _session_from_args(args)
    golden_name = SESSION_GOLDENS.get(session or "")
    if not golden_name and session:
        for prefix, candidate in SESSION_PREFIX_GOLDENS:
            if session.startswith(prefix):
                golden_name = candidate
                break
    if not golden_name:
        return None
    return _read_unique_golden(golden_name)

def _snapshot_golden_for_sequence(args):
