def _send_tmux_special(args):
    if "send-keys" not in args:
        return None
    session = _session_from_args(args)
    if not session:
        return None
    index = args.index("send-keys")
    rest = args[index + 1 :]
    while rest and rest[0].startswith("-"):
        rest.pop(0)
    if not rest or not all(token in SPECIAL for token in rest):
        return None
    try:
        return subprocess.run(["tmux", "send-keys", "-t", session, *rest], timeout=5).returncode
    except Exception:
